<template>
  <WorkbenchShell role="worker" active="orders" title="我的订单" subtitle="当前任务优先展示，按服务进度提交完成凭证或查看结算结果">
    <template #actions><button class="refresh-btn" @click="load">刷新订单</button></template>
    <view class="tabs"><button v-for="item in tabs" :key="item.value" :class="{active:activeTab===item.value}" @click="activeTab=item.value"><text>{{ item.label }}</text><text>{{ item.count }}</text></button></view>
    <view v-if="error" class="error-box"><view><text>订单加载失败</text><text>{{ error }}</text></view><button @click="load">重新加载</button></view>
    <view v-if="filteredOrders.length" class="order-list"><view v-for="order in filteredOrders" :key="oid(order)" class="order-card" :class="{current:order.status==='IN_SERVICE'}">
      <view class="order-accent"/><view class="order-main"><view class="order-head"><view><view class="title-line"><text class="order-title">{{ order.productTitle||productName(order) }}</text><text v-if="order.status==='IN_SERVICE'" class="current-tag">当前任务</text></view><text class="order-no">{{ order.orderNo }}</text></view><text class="order-status" :class="statusTone(order.status)">{{ orderStatusText(order.status) }}</text></view>
        <view class="order-details"><view><text>服务内容</text><text>{{ gameText(order.game||order.productSnapshot?.game) }} · {{ order.region||'区服待确认' }} · {{ serviceTypeText(order.serviceType||order.productSnapshot?.serviceType) }}</text></view><view><text>客户信息</text><text>{{ order.customerUid||'UID 待确认' }} · {{ order.customerNickname||'昵称待确认' }}</text></view><view><text>期望开始</text><text>{{ formatDateTime(order.expectStartAt||order.createdAt) }}</text></view><view><text>预计佣金</text><text class="money">{{ order.commissionFen!=null||order.earningsFen!=null?`¥${fenToYuan(order.commissionFen!=null?order.commissionFen:order.earningsFen)}`:'结算后可见' }}</text></view></view>
        <view v-if="order.verificationRejectReason" class="requirement"><text>验收退回原因</text><text>{{ order.verificationRejectReason }}</text></view>
        <view v-if="order.requirementNote" class="requirement"><text>客户备注</text><text>{{ order.requirementNote }}</text></view>
        <view class="next-step"><view class="step-mark">{{ nextStep(order).mark }}</view><view><text>{{ nextStep(order).title }}</text><text>{{ nextStep(order).description }}</text></view><view class="card-actions"><button v-if="can(order,'acceptAssignment')" class="primary-btn" :disabled="submitting" @click="respondAssignment(order,true)">接受指派</button><button v-if="can(order,'rejectAssignment')" class="danger-link" :disabled="submitting" @click="respondAssignment(order,false)">拒绝指派</button><button v-if="can(order,'releaseOrder')" class="danger-link" @click="openRelease(order)">申请退单</button><button v-if="can(order,'submitCompletion')" class="primary-btn" @click="openComplete(order)">提交完成凭证</button></view></view>
        <view v-if="releaseTarget&&oid(releaseTarget)===oid(order)" class="release-box"><textarea v-model="releaseReason" placeholder="请说明退单原因（必填，将写入订单记录）"/><view><button @click="cancelRelease">取消</button><button class="danger-btn" :disabled="submitting" @click="doRelease">确认退单</button></view></view>
      </view>
    </view></view>
    <view v-else-if="!error" class="empty"><view class="empty-icon">单</view><text>{{ emptyTitle }}</text><text>{{ emptyDescription }}</text><button v-if="activeTab!=='CURRENT'" @click="activeTab='CURRENT'">查看当前任务</button></view>

    <view v-if="completeTarget" class="mask" @click="closeComplete"><view class="dialog" @click.stop><view class="dialog-head"><view><text>提交完成凭证</text><text>{{ completeTarget.orderNo }} · {{ completeTarget.productTitle||productName(completeTarget) }}</text></view><button aria-label="关闭" @click="closeComplete">×</button></view><label class="field"><text>实际产出量</text><view><input v-model="actualOutput" type="digit" placeholder="请输入数字"/><text>{{ completeTarget.outputUnit||'单位' }}</text></view></label><view class="upload-section"><view class="upload-head"><view><text>服务完成凭证</text><text>至少 1 张，最多 9 张，可点击预览</text></view><text :class="{valid:pickedImages.length>0}">{{ pickedImages.length }}/9</text></view><view class="image-grid"><view v-for="(image,index) in pickedImages" :key="image" class="image-item"><image :src="image" mode="aspectFill" @click="previewImage(image)"/><button aria-label="移除凭证" @click="removeImage(index)">×</button></view><button v-if="pickedImages.length<9" class="add-image" @click="chooseImages"><text>＋</text><text>添加凭证</text></button></view></view><view v-if="submitting" class="upload-progress"><view><view :style="{width:`${uploadProgress}%`}"/></view><text>正在上传 {{ uploadedCount }}/{{ pickedImages.length }}</text></view><view class="dialog-note">提交后订单进入“待验收”，客服会核对实际产出和凭证。</view><view class="dialog-actions"><button @click="closeComplete">取消</button><button class="primary-btn" :disabled="submitting" @click="doComplete">{{ submitting?'正在提交…':'确认提交' }}</button></view></view></view>
  </WorkbenchShell>
</template>

<script setup>
import { computed, ref } from 'vue';
import { onShow } from '@dcloudio/uni-app';
import { api, uploadFile } from '../../api.js';
import { confirmAction, fenToYuan, guard, oid, orderStatusText } from '../../common.js';
import { formatDateTime, gameText, serviceTypeText } from '../../utils/display.js';
import WorkbenchShell from '../../components/WorkbenchShell.vue';

const activeTab=ref('CURRENT');const orders=ref([]);const error=ref('');const releaseTarget=ref(null);const releaseReason=ref('');const completeTarget=ref(null);const actualOutput=ref('');const pickedImages=ref([]);const submitting=ref(false);const uploadedCount=ref(0);const can=(order,action)=>Array.isArray(order?.allowedActions)&&order.allowedActions.includes(action);
const groups={CURRENT:['ASSIGN_PENDING','IN_SERVICE'],PENDING:['PENDING_CONFIRM'],COMPLETED:['SETTLED','CANCELLED','REFUNDED','CLOSED']};
const filteredOrders=computed(()=>orders.value.filter((order)=>groups[activeTab.value].includes(order.status)).sort((a,b)=>(a.status==='IN_SERVICE'?-1:0)-(b.status==='IN_SERVICE'?-1:0)||Number(b.updatedAt||b.createdAt||0)-Number(a.updatedAt||a.createdAt||0)));
const tabs=computed(()=>[{value:'CURRENT',label:'当前任务',count:orders.value.filter((order)=>groups.CURRENT.includes(order.status)).length},{value:'PENDING',label:'待客服确认',count:orders.value.filter((order)=>groups.PENDING.includes(order.status)).length},{value:'COMPLETED',label:'已完成',count:orders.value.filter((order)=>groups.COMPLETED.includes(order.status)).length}]);
const uploadProgress=computed(()=>pickedImages.value.length?Math.round(uploadedCount.value/pickedImages.value.length*100):0);const emptyTitle=computed(()=>({CURRENT:'当前没有进行中的任务',PENDING:'暂无待客服确认订单',COMPLETED:'暂无已完成订单'}[activeTab.value]));const emptyDescription=computed(()=>({CURRENT:'可以前往订单池查看并承接新的服务订单。',PENDING:'提交完成凭证后，订单会显示在这里。',COMPLETED:'已结算、取消或退款订单会保留在这里。'}[activeTab.value]));
function productName(order){const snapshot=order.productSnapshot||{};return snapshot.title||snapshot.name||'服务订单';}function statusTone(status){if(status==='SETTLED')return'success';if(['CANCELLED','REFUNDED','CLOSED'].includes(status))return'muted';if(status==='PENDING_CONFIRM')return'warning';return'active';}
function nextStep(order){return {ASSIGN_PENDING:{mark:'1',title:'确认客服指派',description:'请核对服务要求后接受或拒绝本次指派。'},IN_SERVICE:{mark:'2',title:'完成服务并提交凭证',description:'按客户要求完成服务，至少上传一张清晰凭证。'},PENDING_CONFIRM:{mark:'3',title:'等待客服核对',description:'客服核对通过后订单将结算佣金。'},SETTLED:{mark:'✓',title:'订单已结算',description:'佣金已进入钱包，可在钱包流水中查看。'}}[order.status]||{mark:'·',title:orderStatusText(order.status),description:'订单状态已更新，请留意后续通知。'};}
async function load(){error.value='';try{const list=await api.listMyOrders();if(!Array.isArray(list))throw new Error('订单接口格式异常');orders.value=list;}catch(e){error.value=e.message||'加载失败';}}
function openRelease(order){releaseTarget.value=order;releaseReason.value='';}function cancelRelease(){releaseTarget.value=null;releaseReason.value='';}
async function doRelease(){if(!releaseTarget.value)return;if(!releaseReason.value.trim()){uni.showToast({title:'请填写退单原因',icon:'none'});return;}const confirmed=await confirmAction({title:'确认退单',content:'退单后订单将返回订单池，原因会写入订单记录。',confirmText:'确认退单',danger:true});if(!confirmed)return;submitting.value=true;try{await api.releaseOrder(oid(releaseTarget.value),releaseReason.value.trim());uni.showToast({title:'已退单',icon:'success'});cancelRelease();await load();}catch(e){uni.showToast({title:e.message||'退单失败',icon:'none'});}finally{submitting.value=false;}}
function openComplete(order){completeTarget.value=order;actualOutput.value='';pickedImages.value=[];uploadedCount.value=0;}function closeComplete(){if(submitting.value)return;completeTarget.value=null;pickedImages.value=[];uploadedCount.value=0;}function chooseImages(){uni.chooseImage({count:9-pickedImages.value.length,success:(res)=>{pickedImages.value=[...pickedImages.value,...(res.tempFilePaths||[])].slice(0,9);}});}function removeImage(index){pickedImages.value.splice(index,1);}function previewImage(current){uni.previewImage({urls:pickedImages.value,current});}
async function doComplete(){const output=Number(actualOutput.value);if(actualOutput.value===''||Number.isNaN(output)||output<0){uni.showToast({title:'请填写实际产出量',icon:'none'});return;}if(!pickedImages.value.length){uni.showToast({title:'请上传至少 1 张凭证截图',icon:'none'});return;}submitting.value=true;uploadedCount.value=0;try{const attachmentIds=[];for(const path of pickedImages.value){const upload=await uploadFile('complete_proof',path,path.split('/').pop()||'proof.jpg',oid(completeTarget.value));attachmentIds.push(upload.attachmentId||upload.attachment_id||upload.id);uploadedCount.value+=1;}await api.submitCompletion(oid(completeTarget.value),output,attachmentIds);uni.showToast({title:'已提交，等待客服核对',icon:'success'});completeTarget.value=null;pickedImages.value=[];await load();activeTab.value='PENDING';}catch(e){uni.showToast({title:e.message||'提交失败，请重试',icon:'none'});}finally{submitting.value=false;}}
async function respondAssignment(order, accept){
  if(submitting.value)return;
  let reason='';
  if(!accept){const res=await new Promise(resolve=>uni.showModal({title:'拒绝指派',editable:true,placeholderText:'请填写拒绝原因',success:resolve,fail:()=>resolve({confirm:false})}));if(!res.confirm)return;reason=String(res.content||'').trim();if(!reason){uni.showToast({title:'请填写拒绝原因',icon:'none'});return;}}
  submitting.value=true;
  try{if(accept)await api.acceptAssignment(oid(order));else await api.rejectAssignment(oid(order),reason);await load();uni.showToast({title:accept?'已接受，开始服务':'已退回订单池',icon:'success'});}catch(e){uni.showToast({title:e.message||'操作失败',icon:'none'});}finally{submitting.value=false;}
}
onShow(()=>{if(!guard(['WORKER']))return;load();});
</script>

<style lang="scss" scoped>
.refresh-btn{width:auto;height:36px;margin:0;padding:0 13px;color:var(--es-primary);font-size:12px;line-height:36px;background:#fff;border:1px solid #c7d7fe;border-radius:9px}.tabs{margin-bottom:16px;padding:5px;display:flex;gap:4px;background:#e9ecf5;border-radius:11px;width:max-content}.tabs button{width:auto;height:36px;margin:0;padding:0 13px;display:flex;align-items:center;gap:8px;color:#667085;font-size:12px;line-height:36px;background:transparent;border-radius:8px}.tabs button text:last-child{min-width:20px;height:20px;padding:0 6px;line-height:20px;background:rgba(255,255,255,.65);border-radius:999px}.tabs button.active{color:#4338ca;font-weight:700;background:#fff;box-shadow:0 1px 3px rgba(16,24,40,.1)}.error-box{margin-bottom:14px;padding:13px 15px;display:flex;align-items:center;justify-content:space-between;color:#b42318;background:#fef3f2;border:1px solid #fecdca;border-radius:10px}.error-box text{display:block;font-size:12px}.error-box text:first-child{font-size:13px;font-weight:700}.error-box button{width:auto;height:32px;margin:0;padding:0 12px;color:#b42318;font-size:11px;line-height:32px;background:#fff;border:1px solid #fda29b;border-radius:8px}
.order-list{display:flex;flex-direction:column;gap:14px}.order-card{position:relative;overflow:hidden;background:#fff;border:1px solid var(--es-border-soft);border-radius:14px;box-shadow:var(--es-glow)}.order-card.current{border-color:#c7d7fe}.order-accent{position:absolute;top:0;bottom:0;left:0;width:4px;background:#d0d5dd}.order-card.current .order-accent{background:var(--es-primary)}.order-main{padding:19px 20px 19px 23px}.order-head,.title-line,.next-step,.card-actions{display:flex;align-items:center}.order-head{justify-content:space-between;gap:15px}.title-line{gap:9px}.order-title{font-size:16px;font-weight:700}.current-tag{padding:3px 7px;color:#4338ca;font-size:10px;font-weight:600;background:#eef0ff;border-radius:999px}.order-no{display:block;margin-top:5px;color:var(--es-text-dim);font-size:11px}.order-status{padding:5px 9px;color:#4338ca;font-size:11px;font-weight:600;background:#eef0ff;border-radius:999px}.order-status.warning{color:#b54708;background:#fffaeb}.order-status.success{color:#027a48;background:#ecfdf3}.order-status.muted{color:#475467;background:#f2f4f7}.order-details{margin-top:16px;padding:14px 15px;display:grid;grid-template-columns:1.3fr 1.3fr 1fr .7fr;gap:15px;background:#f8fafc;border-radius:10px}.order-details text{display:block}.order-details text:first-child{color:var(--es-text-dim);font-size:10px}.order-details text:last-child{margin-top:5px;overflow:hidden;font-size:12px;font-weight:550;text-overflow:ellipsis;white-space:nowrap}.order-details .money{color:#4338ca;font-size:14px;font-weight:700}.requirement{margin-top:12px;display:flex;gap:8px;color:#475467;font-size:11px}.requirement text:first-child{flex:none;font-weight:700}.next-step{margin-top:15px;padding-top:15px;gap:11px;border-top:1px solid var(--es-border-soft)}.step-mark{width:30px;height:30px;flex:none;display:flex;align-items:center;justify-content:center;color:#4338ca;font-size:12px;font-weight:800;background:#eef0ff;border-radius:50%}.next-step>view:nth-child(2){min-width:0;flex:1}.next-step text{display:block}.next-step text:first-child{font-size:12px;font-weight:650}.next-step text:last-child{margin-top:3px;color:var(--es-text-dim);font-size:10px}.card-actions{gap:8px}.primary-btn,.danger-link,.danger-btn{width:auto;height:36px;margin:0;padding:0 13px;font-size:12px;line-height:36px;border-radius:8px}.primary-btn{color:#fff;font-weight:600;background:var(--es-primary)}.danger-link{color:#b42318;background:#fff;border:1px solid #fda29b}.release-box{margin-top:14px;padding:13px;background:#fef3f2;border:1px solid #fecdca;border-radius:9px}.release-box textarea{width:100%;height:72px;padding:10px;color:var(--es-text);font-size:12px;background:#fff;border:1px solid #fda29b;border-radius:8px}.release-box>view{margin-top:8px;display:flex;justify-content:flex-end;gap:8px}.release-box button{width:auto;height:32px;margin:0;padding:0 12px;color:#475467;font-size:11px;line-height:32px;background:#fff;border:1px solid var(--es-border);border-radius:7px}.release-box .danger-btn{color:#fff;background:#d92d20;border-color:#d92d20}.empty{min-height:350px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:var(--es-text-dim);background:#fff;border:1px solid var(--es-border-soft);border-radius:14px}.empty-icon{width:62px;height:62px;display:flex;align-items:center;justify-content:center;color:var(--es-primary);font-weight:700;background:#eef0ff;border-radius:20px}.empty>text:nth-child(2){margin-top:14px;color:var(--es-text);font-size:15px;font-weight:650}.empty>text:nth-child(3){margin-top:6px;font-size:11px}.empty>button{width:auto;height:34px;margin:16px 0 0;padding:0 13px;color:var(--es-primary);font-size:11px;line-height:34px;background:#fff;border:1px solid #c7d7fe;border-radius:8px}
.mask{position:fixed;inset:0;z-index:90;padding:20px;display:flex;align-items:center;justify-content:center;background:rgba(15,23,42,.58);backdrop-filter:blur(2px)}.dialog{width:min(560px,100%);max-height:calc(100vh - 40px);padding:22px;overflow:auto;background:#fff;border-radius:16px;box-shadow:0 24px 70px rgba(15,23,42,.25)}.dialog-head{display:flex;justify-content:space-between}.dialog-head text{display:block}.dialog-head text:first-child{font-size:17px;font-weight:750}.dialog-head text:last-child{margin-top:5px;color:var(--es-text-dim);font-size:11px}.dialog-head button{width:30px;height:30px;margin:0;padding:0;color:#667085;font-size:20px;line-height:30px;background:#f2f4f7;border-radius:50%}.field{display:block;margin-top:18px}.field>text{display:block;margin-bottom:7px;color:#344054;font-size:12px;font-weight:600}.field>view{height:42px;padding:0 12px;display:flex;align-items:center;border:1px solid var(--es-border);border-radius:9px}.field input{min-width:0;flex:1;height:40px;font-size:13px}.field>view>text{color:var(--es-text-dim);font-size:11px}.upload-section{margin-top:18px}.upload-head{display:flex;justify-content:space-between}.upload-head text{display:block}.upload-head>view text:first-child{font-size:12px;font-weight:650}.upload-head>view text:last-child{margin-top:3px;color:var(--es-text-dim);font-size:10px}.upload-head>text{color:#98a2b3;font-size:11px}.upload-head>text.valid{color:#027a48}.image-grid{margin-top:10px;display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.image-item,.add-image{height:88px;position:relative;overflow:hidden;border-radius:9px}.image-item image{width:100%;height:100%}.image-item button{position:absolute;right:4px;top:4px;width:22px;height:22px;margin:0;padding:0;color:#fff;font-size:14px;line-height:22px;background:rgba(15,23,42,.74);border-radius:50%}.add-image{width:100%;margin:0;padding:0;display:flex;flex-direction:column;align-items:center;justify-content:center;color:var(--es-text-dim);font-size:10px;line-height:1.4;background:#fafbff;border:1px dashed #aeb4fd}.add-image text:first-child{color:var(--es-primary);font-size:22px}.upload-progress{margin-top:14px}.upload-progress>view{height:6px;overflow:hidden;background:#eaecf0;border-radius:99px}.upload-progress>view>view{height:100%;background:var(--es-primary);transition:width .2s}.upload-progress>text{display:block;margin-top:5px;color:var(--es-text-dim);font-size:10px}.dialog-note{margin-top:16px;padding:10px;color:#475467;font-size:11px;background:#f8fafc;border-radius:8px}.dialog-actions{margin-top:18px;display:flex;justify-content:flex-end;gap:8px}.dialog-actions>button:first-child{width:auto;height:36px;margin:0;padding:0 14px;color:#475467;font-size:12px;line-height:36px;background:#fff;border:1px solid var(--es-border);border-radius:8px}
@media(max-width:900px){.order-details{grid-template-columns:1fr 1fr}}@media(max-width:767px){.tabs{width:100%}.tabs button{flex:1;justify-content:center;padding:0 7px}.order-main{padding:16px 15px 16px 19px}.order-head{align-items:flex-start}.order-details{grid-template-columns:1fr}.next-step{align-items:flex-start;flex-wrap:wrap}.card-actions{width:100%;padding-left:41px}.card-actions button{flex:1}.image-grid{grid-template-columns:repeat(3,1fr)}.dialog{padding:18px}.refresh-btn{height:32px;line-height:32px}}
</style>
